'use strict';
const testApi=require('node:test');
const test=(name,fn)=>testApi(name,{concurrency:false},fn);
test.before=testApi.before;
test.after=testApi.after;
const assert=require('node:assert/strict');
const fs=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const {spawn}=require('node:child_process');

let dir, dataFile, child, base;
async function request(method,pathName,body,headers={}){
  const r=await fetch(base+pathName,{method,headers:{'content-type':'application/json','X-Today':'2026-01-01',...headers},body:body===undefined?undefined:JSON.stringify(body)});
  return {status:r.status,json:await r.json()};
}

test.before(async()=>{
  dir=fs.mkdtempSync(path.join(os.tmpdir(),'library-test-'));
  dataFile=path.join(dir,'library.json');
  child=spawn(process.execPath,['server.js'],{env:{...process.env,PORT:'0',DATA_FILE:dataFile},stdio:['ignore','pipe','inherit']});
  let output='';
  await new Promise((resolve,reject)=>{
    child.stdout.on('data',chunk=>{output+=chunk;const m=output.match(/LISTENING_ON_PORT=(\d+)/);if(m){base='http://127.0.0.1:'+m[1];resolve();}});
    child.once('error',reject);
    setTimeout(()=>reject(new Error('server timeout')),5000);
  });
});
test.after(()=>{if(child)child.kill('SIGTERM');fs.rmSync(dir,{recursive:true,force:true});});

test('initial views and static UI',async()=>{
  let r=await request('GET','/api/books');assert.equal(r.status,200);assert.equal(r.json.length,6);assert.ok(r.json.every(b=>Number.isInteger(b.availableCopies)));
  r=await request('GET','/api/members');assert.equal(r.status,200);assert.equal(r.json.length,3);
  r=await request('GET','/api/members/m1');assert.equal(r.status,200);assert.deepEqual(r.json.activeLoans,[]);
  const ui=await fetch(base+'/');assert.equal(ui.status,200);assert.match(await ui.text(),/Neighbourhood Library/);
});

test('validation, loan dates, availability and unknown resources',async()=>{
  let r=await request('POST','/api/loans',{});assert.equal(r.status,400);
  r=await request('POST','/api/loans',{bookId:' ',memberId:'m1'});assert.equal(r.status,400);
  r=await request('POST','/api/loans',{bookId:'missing',memberId:'m1'});assert.equal(r.status,404);
  r=await request('POST','/api/loans',{bookId:'b2',memberId:'m1'});assert.equal(r.status,201);assert.equal(r.json.dueDate,'2026-01-15');
  r=await request('POST','/api/loans',{bookId:'b2',memberId:'m2'});assert.equal(r.status,409);
});

test('holds, reservation, oldest ordering and return fine cap',async()=>{
  let r=await request('POST','/api/holds',{bookId:'b2',memberId:'m2'});assert.equal(r.status,201);
  r=await request('POST','/api/holds',{bookId:'b2',memberId:'m3'});assert.equal(r.status,201);
  r=await request('POST','/api/holds',{bookId:'b1',memberId:'m1'});assert.equal(r.status,409);
  r=await request('POST','/api/loans/l1/renew');assert.equal(r.status,409);
  r=await request('POST','/api/loans/l1/return',undefined,{'X-Today':'2026-03-01'});assert.equal(r.status,200);assert.equal(r.json.fineCents,1000);
  r=await request('POST','/api/loans',{bookId:'b2',memberId:'m3'});assert.equal(r.status,409);
  r=await request('POST','/api/loans',{bookId:'b2',memberId:'m2'});assert.equal(r.status,201);assert.equal(r.json.memberId,'m2');
  r=await request('GET','/api/members/m2');assert.equal(r.status,200);assert.equal(r.json.holds.length,0);
});

test('renewal, limits, payments and fine threshold',async()=>{
  let r=await request('POST','/api/loans',{bookId:'b3',memberId:'m3'});assert.equal(r.status,201);const renewalId=r.json.id;
  r=await request('POST','/api/loans/'+renewalId+'/renew');assert.equal(r.status,200);
  r=await request('POST','/api/loans/'+renewalId+'/renew');assert.equal(r.status,200);
  r=await request('POST','/api/loans/'+renewalId+'/renew');assert.equal(r.status,409);
  const premiumLoans=[renewalId];
  for(const bookId of ['b1','b4','b5','b6']) { r=await request('POST','/api/loans',{bookId,memberId:'m3'});assert.equal(r.status,201);premiumLoans.push(r.json.id); }
  r=await request('POST','/api/loans',{bookId:'b2',memberId:'m3'});assert.equal(r.status,409);
  for(const id of premiumLoans) { r=await request('POST','/api/loans/'+id+'/return',undefined,{'X-Today':'2026-01-01'});assert.equal(r.status,200); }
  r=await request('POST','/api/members/m1/payments',{amount:10});assert.equal(r.status,201);assert.equal(r.json.amountCents,1000);
  r=await request('POST','/api/members/m1/payments',{amount:0.01});assert.equal(r.status,201);assert.equal(r.json.amountCents,1);
  r=await request('POST','/api/members/m1/payments',{amount:'1'});assert.equal(r.status,400);
  r=await request('GET','/api/members/m1');assert.equal(r.status,200);assert.equal(r.json.finesOwedCents,0);
});

test('standard loan limit and unpaid-fine refusal',async()=>{
  let r=await request('POST','/api/loans',{bookId:'b4',memberId:'m1'});assert.equal(r.status,201);const firstLoan=r.json.id;
  r=await request('POST','/api/loans',{bookId:'b5',memberId:'m1'});assert.equal(r.status,201);
  r=await request('POST','/api/loans',{bookId:'b6',memberId:'m1'});assert.equal(r.status,201);
  r=await request('POST','/api/loans',{bookId:'b1',memberId:'m1'});assert.equal(r.status,409);
  r=await request('POST','/api/loans/'+firstLoan+'/return',undefined,{'X-Today':'2026-03-01'});assert.equal(r.status,200);
});

test('fine threshold and premium limit',async()=>{
  let r=await request('POST','/api/loans',{bookId:'b1',memberId:'m2'});assert.equal(r.status,201);
  r=await request('POST','/api/loans/'+r.json.id+'/return',undefined,{'X-Today':'2026-01-16'});assert.equal(r.status,200);assert.equal(r.json.fineCents,25);
  r=await request('POST','/api/members/m2/payments',{amount:0.01});assert.equal(r.status,201);
  r=await request('POST','/api/loans',{bookId:'b4',memberId:'m2'});assert.equal(r.status,201);
  r=await request('POST','/api/loans/'+r.json.id+'/return',undefined,{'X-Today':'2026-03-01'});assert.equal(r.status,200);assert.equal(r.json.fineCents,1000);
  r=await request('POST','/api/loans',{bookId:'b1',memberId:'m2'});assert.equal(r.status,409);
  r=await request('POST','/api/members/m2/payments',{amount:10.25});assert.equal(r.status,201);
  r=await request('POST','/api/loans',{bookId:'b1',memberId:'m2'});assert.equal(r.status,201);
  const m1=await request('GET','/api/members/m1');
  for(const loan of m1.json.activeLoans) { r=await request('POST','/api/loans/'+loan.id+'/return',undefined,{'X-Today':'2026-01-01'});assert.equal(r.status,200); }
  for(const bookId of ['b1','b3','b4','b5','b6']) { r=await request('POST','/api/loans',{bookId,memberId:'m3'});assert.equal(r.status,201); }
  r=await request('POST','/api/loans',{bookId:'b6',memberId:'m3'});assert.equal(r.status,409);
});

test('malformed, missing loan and unknown route',async()=>{
  let r=await fetch(base+'/api/loans',{method:'POST',headers:{'content-type':'application/json'},body:'not json'});assert.equal(r.status,400);
  r=await request('POST','/api/loans/nope/return');assert.equal(r.status,404);
  r=await request('GET','/api/members/nope');assert.equal(r.status,404);
  r=await request('GET','/api/nope');assert.equal(r.status,404);
  assert.ok(fs.existsSync(dataFile));assert.doesNotThrow(()=>JSON.parse(fs.readFileSync(dataFile,'utf8')));
});

