const test=require('node:test'),assert=require('node:assert/strict');
const {session}=require('./helper.cjs');
test('premium limit: five successes, available sixth refused',async()=>{
 const s=await session();try{
  for(const bookId of ['b1','b1','b4','b4','b6']) assert.equal((await s.post('/api/loans',{bookId,memberId:'m3'})).status,201);
  // Fresh seed: b5 has one free copy, no holds or unpaid fines.
  assert.equal((await s.post('/api/loans',{bookId:'b5',memberId:'m3'})).status,409);
 }finally{await s.close();}
});

const test=require('node:test'),assert=require('node:assert/strict');
const {session}=require('./helper.cjs');
test('renewal adds exactly fourteen days to existing due date',async()=>{
 const s=await session();try{
  const loan=await s.post('/api/loans',{bookId:'b1',memberId:'m1'});assert.equal(loan.status,201);assert.equal(loan.body.dueDate,'2026-01-15');
  const renewed=await s.post('/api/loans/'+loan.body.id+'/renew');assert.equal(renewed.status,200);assert.equal(renewed.body.dueDate,'2026-01-29');
 }finally{await s.close();}
});

const test=require('node:test'),assert=require('node:assert/strict');
const {session}=require('./helper.cjs');
test('fine threshold: below and at five allowed, above five refused',async()=>{
 for(const [date,cents,status] of [['2026-02-03',475,201],['2026-02-04',500,201],['2026-02-05',525,409]]){
  const s=await session();try{
   const loan=await s.post('/api/loans',{bookId:'b1',memberId:'m1'});assert.equal(loan.status,201);
   const returned=await s.post('/api/loans/'+loan.body.id+'/return',undefined,date);assert.equal(returned.status,200);assert.equal(returned.body.fineCents,cents);
   assert.equal((await s.post('/api/loans',{bookId:'b4',memberId:'m1'},date)).status,status);
  }finally{await s.close();}
 }
});

